 void ResizeTab(WorkTab tab){if(!tab.attached||tab.detached||tab.lastSize==tab.panel.Size||tab.panel.Width<1||tab.panel.Height<1)return;tab.lastSize=tab.panel.Size;Command(tab,"resize",new Dictionary<string,object>{{"width",tab.panel.Width},{"height",tab.panel.Height}});}
 void LoadAppearance(){try{ApplyAppearance(File.ReadAllText(Path.Combine(root,"appearance.txt")),false);}catch{ApplyAppearance("Paper",false);}}
 void ApplyAppearance(string name,bool save){appearance=name;Color bg,fg,card;switch(name){case "Charcoal":bg=Color.FromArgb(32,35,41);fg=Color.FromArgb(236,237,233);card=Color.FromArgb(43,47,54);break;case "Sketchbook":bg=Color.FromArgb(233,229,221);fg=Color.FromArgb(39,54,58);card=Color.FromArgb(248,246,240);break;case "Plum":bg=Color.FromArgb(39,32,46);fg=Color.FromArgb(240,231,244);card=Color.FromArgb(53,44,63);break;case "Candy":bg=Color.FromArgb(240,230,239);fg=Color.FromArgb(83,54,80);card=Color.FromArgb(255,246,252);break;case "Forest":bg=Color.FromArgb(32,54,48);fg=Color.FromArgb(242,235,210);card=Color.FromArgb(51,78,64);break;case "Blueprint":bg=Color.FromArgb(26,49,70);fg=Color.FromArgb(222,239,245);card=Color.FromArgb(43,70,92);break;default:appearance="Paper";bg=Color.FromArgb(245,238,223);fg=Color.FromArgb(72,58,47);card=Color.FromArgb(255,251,241);break;}BackColor=bg;ForeColor=fg;((QuietTabs)tabs).StripColor=bg;bar.BackColor=bg;bar.ForeColor=fg;status.BackColor=bg;status.ForeColor=fg;foreach(TabPage page in tabs.TabPages)page.BackColor=bg;ThemeChildren(home,bg,fg,card);tabs.Invalidate();foreach(ToolStripItem item in bar.Items)if(item is ToolStripDropDownButton)foreach(ToolStripItem child in ((ToolStripDropDownButton)item).DropDownItems){child.BackColor=bg;child.ForeColor=fg;if(child is ToolStripMenuItem&&new[]{"Sketchbook","Charcoal","Paper","Plum","Candy","Forest","Blueprint"}.Contains(child.Text))((ToolStripMenuItem)child).Checked=child.Text==appearance;}if(save)File.WriteAllText(Path.Combine(root,"appearance.txt"),appearance);if(matchStudioThemes)foreach(var tab in items.Where(x=>x.attached))Command(tab,"theme",new Dictionary<string,object>{{"name",appearance}});}
 Image OutlinedLogo(Image original,Color stroke){var output=new Bitmap(original.Width,original.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var graphics=Graphics.FromImage(output))using(var attributes=new System.Drawing.Imaging.ImageAttributes()){var matrix=new System.Drawing.Imaging.ColorMatrix(new float[][]{new float[]{0,0,0,0,0},new float[]{0,0,0,0,0},new float[]{0,0,0,0,0},new float[]{0,0,0,1,0},new float[]{stroke.R/255f,stroke.G/255f,stroke.B/255f,0,1}});attributes.SetColorMatrix(matrix);foreach(var offset in new[]{new Point(-3,0),new Point(3,0),new Point(0,-3),new Point(0,3),new Point(-2,-2),new Point(2,-2),new Point(-2,2),new Point(2,2)})graphics.DrawImage(original,new Rectangle(offset.X,offset.Y,original.Width,original.Height),0,0,original.Width,original.Height,GraphicsUnit.Pixel,attributes);graphics.DrawImageUnscaled(original,0,0);}return output;}
 void ThemeChildren(Control parent,Color bg,Color fg,Color card){if(Convert.ToString(parent.Tag)=="suite-logo"){parent.BackColor=bg;var picture=parent as PictureBox;if(picture!=null&&approvedSuiteLogo!=null){var previous=picture.Image;picture.Image=OutlinedLogo(approvedSuiteLogo,fg);if(previous!=null)previous.Dispose();}return;}parent.BackColor=bg;parent.ForeColor=fg;foreach(Control child in parent.Controls){ThemeChildren(child,bg,fg,card);if(child is Button){child.BackColor=card;((Button)child).FlatStyle=FlatStyle.Flat;}}}
 int TabAt(Point point){for(int i=0;i<tabs.TabCount;i++)if(tabs.GetTabRect(i).Contains(point))return i;return -1;}
 void MoveTab(TabPage page,int destination){int index=tabs.TabPages.IndexOf(page);if(index<=0||destination<=0||destination>=tabs.TabCount||index==destination)return;var selected=tabs.SelectedTab;opening=true;tabs.SuspendLayout();try{tabs.TabPages.Remove(page);tabs.TabPages.Insert(destination,page);tabs.SelectedTab=selected;items.Sort((a,b)=>tabs.TabPages.IndexOf(a.page).CompareTo(tabs.TabPages.IndexOf(b.page)));}finally{tabs.ResumeLayout();opening=false;}Inventory();tabs.Invalidate();SetStatus("Tab order updated. Your documents stay open.");}
 void DeferMenuDisposal(ContextMenuStrip menu){menu.Closed+=(a,b)=>{if(!IsDisposed&&IsHandleCreated)BeginInvoke(new Action(()=>{if(!menu.IsDisposed)menu.Dispose();}));};}
 void SetupTabs(){tabs.DrawMode=TabDrawMode.OwnerDrawFixed;tabs.DrawItem+=(s,e)=>{bool chosen=e.Index==tabs.SelectedIndex;bool paired=compare!=null&&(tabs.TabPages[e.Index]==compare.page||items.Any(x=>x.panel==comparePanel&&x.page==tabs.TabPages[e.Index]));Color bg=chosen?ControlPaint.Light(BackColor,.18f):BackColor;using(var brush=new SolidBrush(bg))e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,tabs.TabPages[e.Index].Text,Font,Rectangle.Inflate(e.Bounds,-12,-6),ForeColor,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);if(chosen||paired)using(var pen=new Pen(appearance=="Paper"?Color.FromArgb(78,119,106):Color.FromArgb(133,199,194),3))e.Graphics.DrawLine(pen,e.Bounds.Left+8,e.Bounds.Bottom-3,e.Bounds.Right-8,e.Bounds.Bottom-3);};tabs.MouseDown+=(s,e)=>{int index=TabAt(e.Location);if(index<0)return;var page=tabs.TabPages[index];if(e.Button==MouseButtons.Right&&page!=home){tabs.SelectedTab=page;var menu=new ContextMenuStrip();menu.Items.Add("Detach into its own window",null,async(a,b)=>await Detach());menu.Items.Add("Move left",null,(a,b)=>MoveTab(page,tabs.TabPages.IndexOf(page)-1)).Enabled=index>1;menu.Items.Add("Move right",null,(a,b)=>MoveTab(page,tabs.TabPages.IndexOf(page)+1)).Enabled=index<tabs.TabCount-1;menu.Items.Add("Duplicate document in a new tab",null,async(a,b)=>{var source=Current();if(source==null)return;try{await CaptureTab(source);var doc=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(source.folder,"snapshot.json")));Add(source.studio,doc["document"]);}catch(Exception error){SetStatus(error.Message);}});menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Close tab",null,async(a,b)=>await CloseTab());DeferMenuDisposal(menu);menu.Show(tabs,e.Location);}else if(e.Button==MouseButtons.Left&&page!=home){dragTab=page;dragOrigin=e.Location;tabDragging=false;tabs.Capture=true;}};tabs.MouseMove+=(s,e)=>{if(dragTab==null||e.Button!=MouseButtons.Left)return;if(Math.Abs(e.X-dragOrigin.X)+Math.Abs(e.Y-dragOrigin.Y)>12)tabDragging=true;if(tabDragging){int target=TabAt(e.Location);if(target>0)MoveTab(dragTab,target);tabs.Cursor=Cursors.SizeAll;}};tabs.MouseUp+=async(s,e)=>{tabs.Capture=false;var page=dragTab;bool outside=tabDragging&&page!=null&&!new Rectangle(0,0,tabs.Width,tabs.ItemSize.Height+12).Contains(e.Location);dragTab=null;tabDragging=false;tabs.Cursor=Cursors.Default;if(outside){tabs.SelectedTab=page;if(MessageBox.Show(this,"Open this document in its own studio window?","Detach tab",MessageBoxButtons.OKCancel)==DialogResult.OK)await Detach();}};}

void RefreshDetachedMenu(){detachedItems.RemoveAll(t=>t.process==null||t.process.HasExited);detachedMenu.DropDownItems.Clear();detachedMenu.Text="Detached studios"+(detachedItems.Count>0?" · "+detachedItems.Count:"");if(detachedItems.Count==0)detachedMenu.DropDownItems.Add("No detached studios in this session").Enabled=false;if(detachedItems.Count>1){detachedMenu.DropDownItems.Add("Bring back all",null,async(a,b)=>await BringBackAll());detachedMenu.DropDownItems.Add(new ToolStripSeparator());}foreach(var tab in detachedItems){var chosen=tab;detachedMenu.DropDownItems.Add("Bring back "+studios[tab.studio]+" · "+tab.title,null,async(a,b)=>await Reattach(chosen));}}
 async Task BringBackAll(){foreach(var detached in detachedItems.ToArray()){if(items.Count>=12){SetStatus("Some studios remain detached: the workspace holds 12 tabs.");break;}await Reattach(detached);}RefreshDetachedMenu();}
 async Task ProbeChild(WorkTab tab,string script){string file=Path.Combine(tab.folder,"test-result.json");File.Delete(file);Command(tab,"test",new Dictionary<string,object>{{"script",script}});for(int i=0;i<400&&!File.Exists(file);i++)await Task.Delay(50);var result=json.Deserialize<Dictionary<string,object>>(ReadShared(file));if(result==null||result.ContainsKey("error"))throw new Exception("Studio check: "+ReadShared(file));}
 async Task PDFTest(){try{string pdf=Path.Combine(WorkspaceProgram.Test,"document.pdf");using(var opening=Process.Start(new ProcessStartInfo(Exe("library"),"\""+pdf+"\""){UseShellExecute=false,WindowStyle=ProcessWindowStyle.Hidden})){for(int i=0;i<100&&!opening.HasExited;i++)await Task.Delay(50);if(!opening.HasExited)throw new Exception("PDF launched another Library process");}for(int i=0;i<200;i++){await Tick();if(items.Any(x=>x.studio=="library"&&x.attached))break;await Task.Delay(100);}var tab=items.First(x=>x.studio=="library");await ProbeChild(tab,"(async()=>{for(let i=0;i<200&&!(document.querySelector('#dialog').open&&document.querySelector('#pdfReaderView canvas'));i++)await new Promise(r=>setTimeout(r,50));window.__workspaceTestResult=document.querySelector('#dialog').open&&document.querySelector('#pdfReaderView canvas')?{ok:true}:{error:'PDF reader did not open'};})()");Command(tab,"test-preview",new Dictionary<string,object>{{"name","pdf-in-workscape.png"}});await Task.Delay(400);await CloseChild(tab);Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=true,checks=new[]{"Explorer PDF request reuses the open Workscape","Workscape creates and focuses its Library tab","PDF opens directly to a rendered preview"}}));allowClose=true;Close();}catch(Exception e){foreach(var tab in items)Command(tab,"close");Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=false,error=e.ToString()}));allowClose=true;Close();}}
 async Task Reattach(WorkTab tab){if(items.Count>=12){SetStatus("Close a tab before bringing another studio back.");return;}if(tab.process==null||tab.process.HasExited){RefreshDetachedMenu();SetStatus("That studio is closed. Open its saved project in a new tab.");return;}string ack=Path.Combine(tab.folder,"attached.json");File.Delete(ack);tab.detached=false;tab.attached=false;tab.active=true;tab.page.Controls.Clear();tab.page.Controls.Add(tab.panel);items.Add(tab);tabs.TabPages.Add(tab.page);tabs.SelectedTab=tab.page;LinkKeyboard(tab);Command(tab,"attach",new Dictionary<string,object>{{"parent",tab.panel.Handle.ToInt64()},{"width",tab.panel.Width},{"height",tab.panel.Height}});Command(tab,"focus",new Dictionary<string,object>{{"active",true}});for(int i=0;i<120&&!File.Exists(ack);i++)await Task.Delay(50);if(!File.Exists(ack)){SetStatus("Reattaching is still in progress. Your document remains open.");return;}tab.attached=true;tab.lastSize=tab.panel.Size;detachedItems.Remove(tab);File.Delete(Path.Combine(tab.folder,"detached.json"));RefreshDetachedMenu();Inventory();SetStatus("Studio returned to its tab with the same document and undo history.");}
 WorkTab Current(){return items.Find(t=>t.page==tabs.SelectedTab&&!t.detached);}
 async Task Detach(){var tab=Current();if(tab==null||!tab.attached)return;if(compare!=null&&(tab==compare||tab.panel==comparePanel)){EndCompare();await SelectTab();}Command(tab,"detach");for(int i=0;i<100&&!File.Exists(Path.Combine(tab.folder,"detached.json"));i++)await Task.Delay(50);if(!File.Exists(Path.Combine(tab.folder,"detached.json"))||tab.process.HasExited){SetStatus("This studio could not detach yet. Your document remains in this tab.");return;}UnlinkKeyboard(tab);tab.detached=true;tabs.TabPages.Remove(tab.page);items.Remove(tab);detachedItems.Add(tab);RefreshDetachedMenu();Inventory();SetStatus("Document detached into its own studio window. Save it there before closing.");}
 void Compare(){if(compare!=null){EndCompare();SelectTab();SetStatus("Back to one studio. Both documents stay open.");return;}var current=Current();if(current==null){SetStatus("Choose an open studio tab, then Compare.");return;}var other=items.FirstOrDefault(t=>t.id==preferredPartner&&t!=current&&!t.detached)??items.FirstOrDefault(t=>t!=current&&!t.detached);if(other==null){SetStatus("Open another studio tab, then choose your pair.");return;}BeginPair(current,other);}
 void EndCompare(){if(compare==null&&pairSplit==null)return;var primary=items.Find(x=>x.panel==comparePanel);var other=compare;var old=pairSplit;compare=null;comparePanel=null;pairSplit=null;if(old!=null&&!old.IsDisposed){old.Panel1.Controls.Clear();old.Panel2.Controls.Clear();}if(primary!=null&&!primary.page.IsDisposed&&!primary.panel.IsDisposed)primary.page.Controls.Add(primary.panel);if(other!=null&&items.Contains(other)&&!other.page.IsDisposed&&!other.panel.IsDisposed)other.page.Controls.Add(other.panel);if(old!=null&&!old.IsDisposed){var parent=old.Parent;if(parent!=null&&!parent.IsDisposed)parent.Controls.Remove(old);old.Dispose();}compareButton.Checked=false;compareButton.Text="Compare";tabs.Invalidate();}
 readonly HashSet<string> closingTabs=new HashSet<string>();
 async Task CloseTab(){var tab=Current();if(tab==null||closingTabs.Contains(tab.id))return;if(MessageBox.Show(this,"Close this tab? Save the studio project or workspace first if you want a portable backup. Local recovery is retained.","Close tab",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await CloseDocumentTab(tab);}
 async Task<bool> CloseDocumentTab(WorkTab tab){if(tab==null||!items.Contains(tab)||!closingTabs.Add(tab.id))return false;try{if(tab.process!=null&&!tab.process.HasExited)await CaptureTab(tab);if(!await CloseChild(tab))return false;if(compare!=null&&(tab==compare||tab.panel==comparePanel))EndCompare();items.Remove(tab);tabs.TabPages.Remove(tab.page);tab.page.Dispose();Inventory();await SelectTab();return true;}catch(Exception error){SetStatus("Tab kept open: "+error.Message);return false;}finally{closingTabs.Remove(tab.id);}}

 async void OnClose(object sender,FormClosingEventArgs e){if(allowClose)return;e.Cancel=true;if(closing)return;closing=true;try{var answer=MessageBox.Show(this,"Save the open documents together before closing?\n\nYes saves a workspace. No keeps local recovery copies.","Your Jago workspace",MessageBoxButtons.YesNoCancel);if(answer==DialogResult.Cancel)return;if(answer==DialogResult.Yes&&!await Save())return;if(answer==DialogResult.No)foreach(var t in items)await CaptureTab(t);foreach(var tab in items)if(!await CloseChild(tab))return;allowClose=true;timer.Stop();Close();}catch(Exception error){SetStatus("Still open: "+error.Message);}finally{closing=false;}}
 async Task<bool> CloseChild(WorkTab tab){if(tab.process==null||tab.process.HasExited){UnlinkKeyboard(tab);return true;}UnlinkKeyboard(tab);Command(tab,"close");for(int i=0;i<120&&!tab.process.HasExited;i++)await Task.Delay(50);if(!tab.process.HasExited){if(!tab.detached)LinkKeyboard(tab);SetStatus("The studio is still closing. Keep this tab open until it finishes.");return false;}UnlinkKeyboard(tab);return true;}
 void SetStatus(string text){if(status.Text!=text)status.Text=text;}


 object SavedView(){var primary=compare==null?null:items.Find(x=>x.panel==comparePanel);return new{selected=items.IndexOf(Current()),left=items.IndexOf(primary),right=items.IndexOf(compare),vertical=pairVertical,ratio=pairSplit==null?.5:(double)pairSplit.SplitterDistance/Math.Max(1,pairVertical?pairSplit.Height:pairSplit.Width)};}
 void RestoreView(Dictionary<string,object> view,int offset){if(view==null)return;try{int left=Convert.ToInt32(view["left"])+offset,right=Convert.ToInt32(view["right"])+offset,chosen=Convert.ToInt32(view["selected"])+offset;pairVertical=Convert.ToBoolean(view["vertical"]);if(left>=offset&&right>=offset&&left<items.Count&&right<items.Count&&left!=right){BeginPair(items[left],items[right]);double ratio=Math.Max(.15,Math.Min(.85,Convert.ToDouble(view["ratio"])));pairSplit.SplitterDistance=(int)((pairVertical?pairSplit.Height:pairSplit.Width)*ratio);}if(chosen>=offset&&chosen<items.Count)tabs.SelectedTab=items[chosen].page;}catch{SetStatus("Documents opened. Choose Compare to arrange your studios.");}}
 bool IsVisibleTab(WorkTab tab){return tabs.SelectedTab==tab.page||(compare!=null&&pairSplit!=null&&pairSplit.Parent==tabs.SelectedTab&&(tab==compare||tab.panel==comparePanel));}
 void BeginPair(WorkTab first,WorkTab second){if(first==null||second==null||first==second)return;EndCompare();preferredPartner=second.id;compare=second;comparePanel=first.panel;pairSplit=new SplitContainer{Dock=DockStyle.Fill,Orientation=pairVertical?Orientation.Horizontal:Orientation.Vertical,Panel1MinSize=100,Panel2MinSize=100};first.page.Controls.Remove(first.panel);second.page.Controls.Remove(second.panel);tabs.SelectedTab=first.page;first.page.Controls.Add(pairSplit);pairSplit.Panel1.Controls.Add(first.panel);pairSplit.Panel2.Controls.Add(second.panel);pairSplit.SplitterDistance=Math.Max(100,(pairVertical?pairSplit.Height:pairSplit.Width)/2);compareButton.Checked=true;compareButton.Text="Close compare";SelectTab();ResizeTab(first);ResizeTab(second);tabs.Invalidate();SetStatus("Both studios are ready to work in. Drag the divider; choose either tab to keep this pair open.");}
 void PairChoices(){pairMenu.DropDownItems.Clear();var current=Current();if(current==null){pairMenu.DropDownItems.Add("Choose a studio tab first").Enabled=false;return;}foreach(var tab in items.Where(x=>x!=current&&!x.detached)){var partner=tab;var choice=new ToolStripMenuItem(studios[tab.studio]+" · "+tab.title){Checked=compare!=null&&(tab==compare||tab.panel==comparePanel)};choice.Click+=(a,b)=>BeginPair(current,partner);pairMenu.DropDownItems.Add(choice);}pairMenu.DropDownItems.Add(new ToolStripSeparator());pairMenu.DropDownItems.Add(pairVertical?"Arrange left and right":"Arrange above and below",null,(a,b)=>{pairVertical=!pairVertical;if(compare!=null){var primary=items.Find(x=>x.panel==comparePanel);var other=compare;BeginPair(primary,other);}});pairMenu.DropDownItems.Add("Give both studios equal space",null,(a,b)=>{if(pairSplit!=null)pairSplit.SplitterDistance=(pairVertical?pairSplit.Height:pairSplit.Width)/2;});pairMenu.DropDownItems.Add("Swap sides",null,(a,b)=>{if(compare!=null){var first=items.Find(x=>x.panel==comparePanel);var second=compare;BeginPair(second,first);}});}
 void ShowGuide(){using(var guide=new Form{Text="Jago Workscape",Size=new Size(720,650),MinimumSize=new Size(560,460),StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=BackColor,ForeColor=ForeColor,ShowInTaskbar=false}){var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(28),AutoScroll=true};var heading=new Label{Text="Your creative workspace",Font=new Font(Font.FontFamily,22,FontStyle.Bold),Dock=DockStyle.Top,Height=70};var nav=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};var text=new Label{Dock=DockStyle.Fill,Padding=new Padding(8,15,8,8),TextAlign=ContentAlignment.TopLeft};string start="Choose a studio from Home or + Studio. Each tab keeps its own document and undo history.\n\nHome > Manage studios lets you choose an extracted release, check its version and location, or return to the bundled copy. Choices apply to newly opened tabs; existing tabs keep their running version.\n\nCompare opens a working pair. Choose pair lets you pick another tab, swap sides, stack the studios or balance their space. Clicking Compare again returns to one studio.\n\nSwitch between either paired tab without losing the two-view layout. Other tabs pause the pair until you return.\n\nDrag tabs to reorder. Right-click a tab to duplicate or detach it. Detached studios > Bring back returns the live document.";string save="Save workspace keeps editable documents together in a .jagoworkspace file. Save individual studio projects whenever you want separate copies.\n\nLibrary folder references still need the original files. Collect assets into a Library home to keep them together.\n\nHome > Recover a previous session offers your local recovery copies.\n\nCtrl Tab: next tab\nCtrl Shift Tab: previous tab\nCtrl T: Home\nCtrl Alt S: save workspace\n\nHidden studios pause playback and suspend when possible. Both studios in a visible Compare pair remain available.";string rights="Open source. Free forever.\n\nPersonal, professional and commercial use are welcome. Your creations belong to you. Imported assets, fonts and third-party components retain their own licences.\n\nMade by Cameron Jago Lis Illustrates.\n\nJago Workscape is an optional companion. Every studio also works independently.\n\nSource and licence files are included with the download.";foreach(var pair in new[]{Tuple.Create("Getting started",start),Tuple.Create("Saving & shortcuts",save),Tuple.Create("About & rights",rights)}){var value=pair.Item2;var b=new Button{Text=pair.Item1,AutoSize=true,FlatStyle=FlatStyle.Flat,Padding=new Padding(8),BackColor=ControlPaint.Light(BackColor,.12f),ForeColor=ForeColor};b.Click+=(a,e)=>text.Text=value;nav.Controls.Add(b);}text.Text=start;var close=new Button{Text="Back to creating",Dock=DockStyle.Bottom,Height=44,FlatStyle=FlatStyle.Flat,BackColor=ControlPaint.Light(BackColor,.12f),ForeColor=ForeColor};close.Click+=(a,b)=>guide.Close();body.Controls.Add(text);body.Controls.Add(nav);body.Controls.Add(heading);guide.Controls.Add(body);guide.Controls.Add(close);guide.AcceptButton=close;guide.CancelButton=close;if(WorkspaceProgram.Test!=null){var shotTimer=new System.Windows.Forms.Timer{Interval=300};shotTimer.Tick+=(a,b)=>{shotTimer.Stop();using(var image=new Bitmap(guide.Width,guide.Height)){guide.DrawToBitmap(image,new Rectangle(0,0,guide.Width,guide.Height));image.Save(Path.Combine(WorkspaceProgram.Test,"guide.png"));}guide.Close();shotTimer.Dispose();};shotTimer.Start();}guide.ShowDialog(this);}}
 protected override bool ProcessCmdKey(ref Message msg,Keys keys){if(keys==(Keys.Control|Keys.Tab)){tabs.SelectedIndex=(tabs.SelectedIndex+1)%tabs.TabCount;return true;}if(keys==(Keys.Control|Keys.Shift|Keys.Tab)){tabs.SelectedIndex=(tabs.SelectedIndex-1+tabs.TabCount)%tabs.TabCount;return true;}if(keys==(Keys.Control|Keys.Alt|Keys.S)){Save();return true;}if(keys==(Keys.Control|Keys.T)){tabs.SelectedTab=home;return true;}var child=Current();Keys letter=keys&Keys.KeyCode;if(child!=null&&child.attached&&((keys&Keys.Control)!=0&&(letter==Keys.Z||letter==Keys.Y||letter==Keys.S)||keys==Keys.Delete)){Command(child,"shortcut",new Dictionary<string,object>{{"key",letter==Keys.Delete?"Delete":letter.ToString().ToLowerInvariant()},{"shift",(keys&Keys.Shift)!=0}});return true;}return base.ProcessCmdKey(ref msg,keys);}async Task Test(){var checks=new List<string>();Action<string> note=message=>{checks.Add(message);Atomic(Path.Combine(WorkspaceProgram.Test,"progress.json"),json.Serialize(checks));};try{Directory.CreateDirectory(WorkspaceProgram.Test);using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(WorkspaceProgram.Test,"home.png"));}foreach(string theme in new[]{"Sketchbook","Charcoal","Paper","Plum","Candy","Forest","Blueprint"}){ApplyAppearance(theme,true);if(appearance!=theme)throw new Exception("Theme failed");}LoadAppearance();using(var stripImage=new Bitmap(tabs.Width,tabs.Height)){tabs.DrawToBitmap(stripImage,new Rectangle(0,0,tabs.Width,tabs.Height));Color sampled=stripImage.GetPixel(tabs.Width-20,20);if(sampled.ToArgb()!=BackColor.ToArgb())throw new Exception("Tab strip theme background differs: "+sampled);stripImage.Save(Path.Combine(WorkspaceProgram.Test,"themed-tab-strip.png"));}note("Unused tab strip follows the Blueprint theme");note("Seven persistent workspace appearances");ShowGuide();note("Themed guide and About rights navigation");var saved=new List<Tuple<string,object>>();foreach(string studio in studios.Keys){var tab=Add(studio);for(int i=0;i<300&&!tab.attached;i++){await Tick();await Task.Delay(100);}if(!tab.attached)throw new Exception(studio+" did not attach");await CaptureTab(tab);var ready=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(tab.folder,"attached.json")));if(GetParent(new IntPtr(Convert.ToInt64(ready["handle"])))!=tab.panel.Handle)throw new Exception(studio+" was not embedded");note(studio+" native embedding and capture");var snapshot=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(tab.folder,"snapshot.json")));var doc=snapshot["document"] as Dictionary<string,object>;if(doc!=null){if(doc.ContainsKey("name"))doc["name"]="Workspace retained edit "+studio;else if(studio=="repeat"){var settings=doc["settings"] as Dictionary<string,object>;settings["seed"]="67891";}}saved.Add(Tuple.Create(studio,snapshot["document"]));}foreach(var checkedTab in items){string checkFile=Path.Combine(checkedTab.folder,"test-result.json");File.Delete(checkFile);Command(checkedTab,"test",new Dictionary<string,object>{{"script","(async()=>{try{for(const name of ['Sketchbook','Charcoal','Paper','Plum','Candy','Forest','Blueprint']){if(!JagoSharedThemes.apply(name))throw Error('Missing '+name);await new Promise(r=>setTimeout(r,40));const expected=JagoSharedThemes.palettes[name.toLowerCase()].bg,actual=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();if(expected!==actual)throw Error(name+' background '+actual);}const tools=document.querySelector('.tools');if(tools&&getComputedStyle(tools).backgroundColor!=='rgb(43, 70, 92)')throw Error('Toolbar retained an old theme');window.__workspaceTestResult={ok:true};}catch(e){window.__workspaceTestResult={error:e.message};}})()"}});for(int i=0;i<300&&!File.Exists(checkFile);i++)await Task.Delay(50);var checkedResult=json.Deserialize<Dictionary<string,object>>(ReadShared(checkFile));if(checkedResult==null||checkedResult.ContainsKey("error"))throw new Exception(checkedTab.studio+" theme verification: "+ReadShared(checkFile));note(checkedTab.studio+" seven shared interface palettes and themed toolbar");}
 matchStudioThemes=true;ApplyAppearance("Forest",true);for(int themeWait=0;themeWait<30;themeWait++){await Tick();await Task.Delay(150);}foreach(var themedTab in items){var themeState=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(themedTab.folder,"state.json")));if(!themeState.ContainsKey("theme")||Convert.ToString(themeState["theme"])!="forest")throw new Exception("Shared theme failed in "+themedTab.studio);note(themedTab.studio+" matches Workscape Forest appearance");Command(themedTab,"test-preview",new Dictionary<string,object>{{"name",themedTab.studio+"-forest.png"}});}matchStudioThemes=false;var selectedBefore=tabs.SelectedTab;MoveTab(items[0].page,tabs.TabCount-1);if(tabs.SelectedTab!=selectedBefore||items.Last().studio!="wobble")throw new Exception("Tab order failed");note("Reordering keeps selected document and updates saved order");string label=items[0].page.Text;int draws=0;DrawItemEventHandler countDraw=(sender,ev)=>draws++;tabs.DrawItem+=countDraw;await Tick();await Task.Delay(850);await Tick();tabs.DrawItem-=countDraw;if(items[0].page.Text!=label||draws>1)throw new Exception("Idle tabs redraw unnecessarily: "+draws);note("Idle polling does not repaint stable tab labels");Compare();await Task.Delay(500);if(compare==null)throw new Exception("Compare failed");note("Side-by-side native panels");var pairPrimary=items.Find(x=>x.panel==comparePanel);var pairOther=compare;tabs.SelectedTab=pairOther.page;await SelectTab();if(compare!=pairOther||pairSplit.Parent!=pairOther.page||!pairPrimary.active||!pairOther.active)throw new Exception("Pair focus lost");note("Switch paired tabs retains both active studios");tabs.SelectedTab=home;await SelectTab();if(compare==null||pairPrimary.active||pairOther.active)throw new Exception("Hidden pair state failed");tabs.SelectedTab=pairPrimary.page;await SelectTab();if(!pairPrimary.active||!pairOther.active)throw new Exception("Pair resume failed");note("Hidden pair suspends and resumes without closing");var replacement=items.First(x=>x!=pairPrimary&&x!=pairOther);BeginPair(pairPrimary,replacement);await Task.Delay(500);if(compare!=replacement)throw new Exception("Partner choice failed");note("Choose any open tab as partner");var savedView=json.Deserialize<Dictionary<string,object>>(json.Serialize(SavedView()));EndCompare();RestoreView(savedView,0);if(compare!=replacement)throw new Exception("Saved pair restoration failed");note("Saved workspace view restores selected pair");Compare();if(compare!=null)throw new Exception("Compare toggle failed");note("Compare button toggles back to a single studio");foreach(var tab in items.ToArray()){if(!await CloseChild(tab))throw new Exception("Child did not close: "+tab.studio);tabs.TabPages.Remove(tab.page);items.Remove(tab);}await Task.Delay(1200);foreach(var doc in saved){var tab=Add(doc.Item1,doc.Item2);for(int i=0;i<300&&!tab.attached;i++){await Tick();await Task.Delay(100);}if(!tab.attached)throw new Exception(doc.Item1+" did not restore");await CaptureTab(tab);note(doc.Item1+" editable restoration");}foreach(var retained in items){await CaptureTab(retained);var snap=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(retained.folder,"snapshot.json")));var doc=snap["document"] as Dictionary<string,object>;if(doc.ContainsKey("name")&&Convert.ToString(doc["name"])!="Workspace retained edit "+retained.studio)throw new Exception("Edited name lost in "+retained.studio);if(retained.studio=="repeat"&&Convert.ToString((doc["settings"] as Dictionary<string,object>)["seed"])!="67891")throw new Exception("Edited seed lost in Repeat");note(retained.studio+" retains edited document while hidden");}var detached=Current();await Detach();var handle=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(detached.folder,"detached.json")));await Task.Delay(500);if(detached.process.HasExited)throw new Exception("Detached studio closed unexpectedly");if(GetParent(new IntPtr(Convert.ToInt64(handle["handle"])))!=IntPtr.Zero)throw new Exception("Detach failed");note("Detach retains native independent window");await Reattach(detached);await CaptureTab(detached);var reattachAck=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(detached.folder,"attached.json")));if(GetParent(new IntPtr(Convert.ToInt64(reattachAck["handle"])))!=detached.panel.Handle)throw new Exception("Reattach failed");note("Detached studio returns with its live editable document");await Detach();tabs.SelectedTab=items[0].page;await Detach();RefreshDetachedMenu();if(!detachedMenu.DropDownItems.Cast<ToolStripItem>().Any(x=>x.Text=="Bring back all"))throw new Exception("Bring back all is missing");await BringBackAll();if(detachedItems.Count!=0||items.Count!=7)throw new Exception("Bring back all failed");note("Bring back all restores multiple live studio windows");var libraryTab=items.First(x=>x.studio=="library");tabs.SelectedTab=libraryTab.page;await ProbeChild(libraryTab,"(async()=>{try{document.querySelector('#dialog').close();await JagoLibrary.loadProject(new File([JSON.stringify({version:1,name:'Workspace undo check',roots:[],assets:[],recipes:[],layout:{width:400,height:400,background:'#ffffff',layers:[]}})],'test.jagolibrary'));JagoLibrary.setWorkspace('production');JagoLibrary.addText();checkpoint();state.layout.layers[0].x=200;renderProduction();document.querySelector('#canvas').focus();window.__workspaceTestResult={ok:true};}catch(e){window.__workspaceTestResult={error:e.message};}})()");var keyMessage=Message.Create(Handle,0x100,new IntPtr((int)Keys.Z),IntPtr.Zero);ProcessCmdKey(ref keyMessage,Keys.Control|Keys.Z);await ProbeChild(libraryTab,"window.__workspaceTestResult=state.layout.layers[0].x===40?{ok:true}:{error:'Workspace undo did not restore artwork'}");note("Ctrl Z from Workscape reaches the embedded studio undo history");foreach(var tab in items)if(!await CloseChild(tab))throw new Exception("Studio did not close cleanly");await Task.Delay(100);Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=true,checks=checks}));allowClose=true;Close();}catch(Exception e){foreach(var tab in items)Command(tab,"close");Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=false,error=e.ToString(),checks=checks}));allowClose=true;Close();}}
